// `asset/` namespace: files with a path CHOSEN by the client (`{visibility}/asset/{path}`), unlike
// image/video/file whose path is generated by the worker (`{visibility}/{kind}/{id}/{file}`). Used by private
// exports from CI (upload tokens scoped to a prefix) and will be reused by public files + a sync script. Pure: no
// runtime dependencies, shared by the SDK and the worker.

export const ASSET_NAMESPACE = "asset";

/** Max depth of an asset's path (segments), not counting the namespace or visibility. */
export const MAX_ASSET_PATH_DEPTH = 16;
/** Max length of an asset's path (normalized). */
export const MAX_ASSET_PATH_LENGTH = 512;

const SAFE_SEGMENT = /^[A-Za-z0-9._-]+$/;
const VISIBILITY_SEGMENTS = new Set(["public", "private"]);
// Reserved by the worker: image transforms store their variants under `{key}/__variants/…`. An asset with that
// segment would collide with another asset's variant (and get deleted along with it).
const RESERVED_SEGMENTS = new Set(["__variants"]);

function isSafeSegment(segment: string): boolean {
	return SAFE_SEGMENT.test(segment) && segment !== "." && segment !== ".." && !RESERVED_SEGMENTS.has(segment);
}

function assetSegments(raw: unknown): string[] | null {
	if (typeof raw !== "string") return null;
	const trimmed = raw.trim().replace(/^\/+/, "");
	if (trimmed.length === 0 || trimmed.length > MAX_ASSET_PATH_LENGTH) return null;
	return trimmed.split("/");
}

/**
 * Normalizes a FILE's path within the namespace (`exports/inst-1/pkg.zip`). `null` = invalid: empty, `..`,
 * `.`, empty segments (`a//b`), characters outside `[A-Za-z0-9._-]` (including `%`: nothing encoded), a
 * trailing slash, the reserved `__variants` segment, too deep/long, or starting with a visibility or with
 * `asset/` (would escape the namespace).
 */
export function normalizeAssetPath(raw: unknown): string | null {
	const segments = assetSegments(raw);
	if (!segments || segments.length > MAX_ASSET_PATH_DEPTH) return null;
	if (!segments.every(isSafeSegment)) return null;
	if (VISIBILITY_SEGMENTS.has(segments[0]) || segments[0] === ASSET_NAMESPACE) return null;
	return segments.join("/");
}

/** Normalizes a PREFIX within the namespace (`exports/inst-1/`): same rules, always with a trailing `/`. */
export function normalizeAssetPrefix(raw: unknown): string | null {
	if (typeof raw !== "string") return null;
	const path = normalizeAssetPath(raw.trim().replace(/\/+$/, ""));
	return path ? `${path}/` : null;
}

/** Path relative to the storage prefix (without visibility) of an asset: `asset/{path}`. */
export function assetRelativePath(assetPath: string): string {
	return `${ASSET_NAMESPACE}/${assetPath}`;
}

/** Virtual key of an asset: `{visibility}/asset/{path}`. */
export function assetKey(visibility: "public" | "private", assetPath: string): string {
	return `${visibility}/${assetRelativePath(assetPath)}`;
}

/** Is the virtual key (`{visibility}/asset/…`) an asset? With or without visibility in front. */
export function isAssetKey(key: string): boolean {
	const segments = key.split("/");
	const offset = VISIBILITY_SEGMENTS.has(segments[0] ?? "") ? 1 : 0;
	return segments[offset] === ASSET_NAMESPACE && segments.length > offset + 1;
}
